hr = {"kim": "결제개발", "lee": "정산운영", "park": "퇴사"}
grants = [
    ("kim",  "pay-db",   "read"),
    ("lee",  "pay-db",   "admin"),
    ("park", "pay-db",   "read"),
    ("choi", "batch-ui", "approve"),
]
need = {"결제개발": {"read"}, "정산운영": {"read"}}
for user, system, right in grants:
    dept = hr.get(user)
    if dept is None:
        print(f"{user:5} {system:8} {right:7} -> 명부에 없음(외부·공용 계정?)")
    elif dept == "퇴사":
        print(f"{user:5} {system:8} {right:7} -> 퇴사자 권한 남음")
    elif right not in need.get(dept, set()):
        print(f"{user:5} {system:8} {right:7} -> {dept} 업무에 필요 없는 권한")

uses = [
    {"name": "상담 요약", "customer_effect": False, "human_final": True, "personal_data": True},
    {"name": "판매자 대출 심사", "customer_effect": True, "human_final": False, "personal_data": True},
    {"name": "이상거래 탐지", "customer_effect": True, "human_final": True, "personal_data": True},
    {"name": "코드 리뷰 도우미", "customer_effect": False, "human_final": True, "personal_data": False},
]
for u in uses:
    flags = []
    if u["customer_effect"] and not u["human_final"]:
        flags.append("자동화된 결정 — 설명·거부 절차 확인")
    if u["personal_data"]:
        flags.append("개인(신용)정보 처리 근거 확인")
    print(u["name"], ":", " / ".join(flags) or "기본 점검만")
